import{_ as r,o as a,c as t,a6 as o}from"./chunks/framework.DNkVJs23.js";const u=JSON.parse('{"title":"À propos de Sapphire Star Codex","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://eurekaffeine.github.io/sapphire-star-codex/fr/others/"}],["meta",{"property":"og:url","content":"https://eurekaffeine.github.io/sapphire-star-codex/fr/others/"}],["meta",{"property":"og:title","content":"À propos de Sapphire Star Codex | Sapphire Star Codex"}],["meta",{"property":"og:description","content":"Données Monster Hunter et recherche de sets pour Wilds, Rise avec Sunbreak et World avec Iceborne."}]]},"headers":[],"relativePath":"fr/others/index.md","filePath":"fr/others/index.md"}'),s={name:"fr/others/index.md"};function n(i,e,p,l,d,c){return a(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="a-propos-de-sapphire-star-codex" tabindex="-1">À propos de Sapphire Star Codex <a class="header-anchor" href="#a-propos-de-sapphire-star-codex" aria-label="Permalink to &quot;À propos de Sapphire Star Codex&quot;">​</a></h1><h2 id="le-projet" tabindex="-1">Le projet <a class="header-anchor" href="#le-projet" aria-label="Permalink to &quot;Le projet&quot;">​</a></h2><p>Sapphire Star Codex réunit des données Monster Hunter et une recherche de sets d’armure. L’application est développée indépendamment par le créateur de <a href="https://eurekaffeine.github.io/pocket-gallery/" target="_blank" rel="noreferrer">Pocket Gallery</a>. Elle est gratuite, sans publicité ni fonctions payantes.</p><p>Android est disponible sur <a href="https://play.google.com/store/apps/details?id=com.eurekaffeine.mhd" target="_blank" rel="noreferrer">Google Play</a> et HarmonyOS sur <a href="https://appgallery.huawei.com/app/detail?id=com.eurekaffeine.monsterhunterdex&amp;channelId=SHARE&amp;source=appshare" target="_blank" rel="noreferrer">AppGallery</a>. La version iOS est en préparation. Consultez les <a href="./../#download">téléchargements</a> ; la disponibilité dépend de la région et de l’appareil.</p><h2 id="retours-et-participation" tabindex="-1">Retours et participation <a class="header-anchor" href="#retours-et-participation" aria-label="Permalink to &quot;Retours et participation&quot;">​</a></h2><p>Pour signaler un problème, précisez le jeu, l’entrée concernée, la langue, les étapes et une source vérifiable. Masquez les données personnelles des captures. Contact : <a href="mailto:eurekaffeine.work@gmail.com" target="_blank" rel="noreferrer">eurekaffeine.work@gmail.com</a>. Le partage de l’application, les corrections et le <a href="./../support/">soutien volontaire</a> sont également appréciés.</p><h2 id="sources-et-droits" tabindex="-1">Sources et droits <a class="header-anchor" href="#sources-et-droits" aria-label="Permalink to &quot;Sources et droits&quot;">​</a></h2><p>Les données proviennent notamment de <a href="https://docs.wilds.mhdb.io/" target="_blank" rel="noreferrer">MHDB Wilds</a>, <a href="https://mhw-db.com/" target="_blank" rel="noreferrer">MHW DB</a> et de fichiers de jeu, avec vérification communautaire. Des omissions ou erreurs restent possibles. Les noms, images et données de Monster Hunter appartiennent à CAPCOM ; les demandes de retrait seront respectées. Le code adapté de Pocket Gallery est sous licence MIT, qui ne couvre pas les illustrations ni les données de jeu.</p>',8)])])}const f=r(s,[["render",n]]);export{u as __pageData,f as default};
